#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* Session ticket validation for a custom TLS-like protocol */

#define MAX_EXTENSIONS 32
#define TICKET_HEADER_SIZE 16
#define MAX_TICKET_SIZE 4096

typedef struct {
    uint16_t type;
    uint16_t length;
    uint8_t *data;
} extension_t;

typedef struct {
    uint8_t version;
    uint8_t cipher_suite;
    uint16_t session_id_len;
    uint8_t session_id[32];
    uint16_t num_extensions;
    extension_t extensions[MAX_EXTENSIONS];
    uint16_t ticket_lifetime;
    uint8_t master_secret[48];
} session_ticket_t;

/* Parse variable-length integer from wire format */
static int parse_vlen_int(const uint8_t *buf, size_t buf_len, size_t *offset, uint32_t *out_val) {
    if (*offset >= buf_len) return -1;
    uint8_t first = buf[*offset];

    if ((first & 0x80) == 0) {
        /* Single byte encoding: 0-127 */
        *out_val = first;
        *offset += 1;
        return 0;
    } else if ((first & 0xC0) == 0x80) {
        /* Two byte encoding: 128-16383 */
        if (*offset + 1 >= buf_len) return -1;
        *out_val = ((uint32_t)(first & 0x3F) << 8) | buf[*offset + 1];
        *offset += 2;
        return 0;
    } else {
        /* Four byte encoding */
        if (*offset + 3 >= buf_len) return -1;
        *out_val = ((uint32_t)(first & 0x3F) << 24) |
                   ((uint32_t)buf[*offset + 1] << 16) |
                   ((uint32_t)buf[*offset + 2] << 8) |
                   (uint32_t)buf[*offset + 3];
        *offset += 4;
        return 0;
    }
}

/* Compute total size needed for decoded extensions */
static int compute_extensions_size(const uint8_t *buf, size_t buf_len, 
                                    size_t start_offset, uint16_t num_ext,
                                    uint32_t *total_size) {
    size_t offset = start_offset;
    uint32_t accumulated = 0;

    for (uint16_t i = 0; i < num_ext; i++) {
        /* Skip extension type (2 bytes) */
        if (offset + 2 > buf_len) return -1;
        offset += 2;

        /* Read extension data length */
        uint32_t ext_len;
        if (parse_vlen_int(buf, buf_len, &offset, &ext_len) != 0) return -1;

        /* Validate extension data is within buffer */
        if (offset + ext_len > buf_len) return -1;
        offset += ext_len;

        /* Accumulate total decoded size */
        accumulated += ext_len;
    }

    *total_size = accumulated;
    return 0;
}

/* 
 * Decode extensions from wire format into session ticket.
 * The caller has pre-validated via compute_extensions_size.
 * Returns 0 on success, -1 on error.
 */
static int decode_extensions(const uint8_t *buf, size_t buf_len,
                             size_t start_offset, session_ticket_t *ticket,
                             uint8_t *ext_data_pool, uint32_t pool_size) {
    size_t offset = start_offset;
    uint32_t pool_offset = 0;

    for (uint16_t i = 0; i < ticket->num_extensions; i++) {
        /* Read extension type */
        ticket->extensions[i].type = (buf[offset] << 8) | buf[offset + 1];
        offset += 2;

        /* Read extension data length using variable-length encoding */
        uint32_t ext_len;
        if (parse_vlen_int(buf, buf_len, &offset, &ext_len) != 0) return -1;

        ticket->extensions[i].length = (uint16_t)ext_len;

        /* Copy extension data into pool */
        /* Safety check: ensure we don't overflow the pool */
        if (pool_offset + ext_len > pool_size) return -1;

        memcpy(ext_data_pool + pool_offset, buf + offset, ext_len);
        ticket->extensions[i].data = ext_data_pool + pool_offset;
        pool_offset += ext_len;
        offset += ext_len;
    }

    return 0;
}

/*
 * Parse and validate a session resumption ticket.
 * buf: raw ticket bytes from network
 * buf_len: length of buf
 * out_ticket: parsed ticket structure
 * Returns 0 on success, negative on error.
 */
int parse_session_ticket(const uint8_t *buf, size_t buf_len, session_ticket_t *out_ticket) {
    if (!buf || !out_ticket || buf_len < TICKET_HEADER_SIZE) return -1;
    if (buf_len > MAX_TICKET_SIZE) return -1;

    memset(out_ticket, 0, sizeof(session_ticket_t));

    size_t offset = 0;

    /* Parse header fields */
    out_ticket->version = buf[offset++];
    out_ticket->cipher_suite = buf[offset++];

    /* Session ID length (2 bytes, big-endian) */
    out_ticket->session_id_len = (buf[offset] << 8) | buf[offset + 1];
    offset += 2;

    if (out_ticket->session_id_len > 32) return -1;
    memcpy(out_ticket->session_id, buf + offset, out_ticket->session_id_len);
    offset += out_ticket->session_id_len;

    /* Number of extensions (2 bytes, big-endian) */
    if (offset + 2 > buf_len) return -1;
    out_ticket->num_extensions = (buf[offset] << 8) | buf[offset + 1];
    offset += 2;

    if (out_ticket->num_extensions > MAX_EXTENSIONS) return -1;

    /* Pre-compute total extension data size for allocation */
    uint32_t total_ext_size;
    if (compute_extensions_size(buf, buf_len, offset, 
                                out_ticket->num_extensions, &total_ext_size) != 0) {
        return -2;
    }

    /* Allocate pool for extension data */
    uint8_t *ext_pool = NULL;
    if (total_ext_size > 0) {
        ext_pool = (uint8_t *)malloc(total_ext_size);
        if (!ext_pool) return -3;
    }

    /* Decode extensions - uses same buffer, re-parses from same offset */
    if (decode_extensions(buf, buf_len, offset, out_ticket, 
                          ext_pool, total_ext_size) != 0) {
        free(ext_pool);
        return -4;
    }

    return 0;
}

/*
 * Renew a session ticket by appending a renewal extension.
 * This is called when the server decides to extend the ticket lifetime.
 * The function modifies the ticket in-place and re-serializes.
 */
int renew_session_ticket(session_ticket_t *ticket, const uint8_t *renewal_data,
                         uint16_t renewal_len, uint8_t *out_buf, size_t out_buf_size) {
    if (!ticket || !renewal_data || !out_buf) return -1;
    if (ticket->num_extensions >= MAX_EXTENSIONS) return -1;

    /* Add renewal extension */
    uint16_t idx = ticket->num_extensions;
    ticket->extensions[idx].type = 0xFF01; /* renewal type */
    ticket->extensions[idx].length = renewal_len;
    ticket->extensions[idx].data = (uint8_t *)renewal_data;
    ticket->num_extensions++;

    /* Serialize the ticket back to wire format */
    size_t write_offset = 0;

    /* Header */
    if (write_offset + 4 > out_buf_size) return -1;
    out_buf[write_offset++] = ticket->version;
    out_buf[write_offset++] = ticket->cipher_suite;
    out_buf[write_offset++] = (ticket->session_id_len >> 8) & 0xFF;
    out_buf[write_offset++] = ticket->session_id_len & 0xFF;

    /* Session ID */
    if (write_offset + ticket->session_id_len > out_buf_size) return -1;
    memcpy(out_buf + write_offset, ticket->session_id, ticket->session_id_len);
    write_offset += ticket->session_id_len;

    /* Extension count */
    if (write_offset + 2 > out_buf_size) return -1;
    out_buf[write_offset++] = (ticket->num_extensions >> 8) & 0xFF;
    out_buf[write_offset++] = ticket->num_extensions & 0xFF;

    /* Serialize each extension */
    for (uint16_t i = 0; i < ticket->num_extensions; i++) {
        /* Extension type (2 bytes) */
        if (write_offset + 2 > out_buf_size) return -1;
        out_buf[write_offset++] = (ticket->extensions[i].type >> 8) & 0xFF;
        out_buf[write_offset++] = ticket->extensions[i].type & 0xFF;

        /* Extension length - use variable-length encoding */
        uint16_t elen = ticket->extensions[i].length;
        if (elen < 128) {
            if (write_offset + 1 > out_buf_size) return -1;
            out_buf[write_offset++] = (uint8_t)elen;
        } else {
            if (write_offset + 2 > out_buf_size) return -1;
            out_buf[write_offset++] = 0x80 | ((elen >> 8) & 0x3F);
            out_buf[write_offset++] = elen & 0xFF;
        }

        /* Extension data */
        if (write_offset + elen > out_buf_size) return -1;
        if (ticket->extensions[i].data) {
            memcpy(out_buf + write_offset, ticket->extensions[i].data, elen);
        }
        write_offset += elen;
    }

    return (int)write_offset;
}

/*
 * Process incoming ticket for session resumption.
 * Validates, optionally renews, and produces response.
 */
int process_resumption_request(const uint8_t *client_ticket, size_t ticket_len,
                               uint8_t *response_buf, size_t response_buf_size) {
    session_ticket_t ticket;
    int rc;

    rc = parse_session_ticket(client_ticket, ticket_len, &ticket);
    if (rc != 0) return rc;

    /* Validate version */
    if (ticket.version != 0x03) {
        return -10;
    }

    /* Check if ticket needs renewal (lifetime extension) */
    uint8_t renewal_token[64];
    memset(renewal_token, 0x42, sizeof(renewal_token));

    /* Compute response size estimate using safe unsigned arithmetic.
     * The estimate includes: header(4) + session_id(32 max) + ext_count(2) + 
     * extensions(variable) + renewal(~70)
     */
    uint32_t size_estimate = (uint32_t)TICKET_HEADER_SIZE + 
                             (uint32_t)ticket.session_id_len + 
                             (uint32_t)ticket.num_extensions * 130u + 70u;

    /* Validate response buffer is sufficient */
    if (size_estimate > (uint32_t)response_buf_size) {
        return -11;
    }

    rc = renew_session_ticket(&ticket, renewal_token, 64, response_buf, response_buf_size);
    return rc;
}
